//! Integration tests for MDict using the synthetic test.mdx fixture.
//!
//! Tests the full public API path: opendict::open() → Dictionary trait.
//!
//! The fixture contains 3 entries (v2.0, UTF-8, zlib, no encryption):
//!   foo   → "bar"
//!   hello → "<b>hello</b> greeting"
//!   test  → "test data here"
//!
//! Generated by: cargo run --example gen_mdx_fixture
//!
//! Unit tests for MdictFile internals live in src/mdict/file.rs.

use std::path::PathBuf;

fn fixture_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("test.mdx")
}

#[test]
fn full_dictionary_lookup() {
    let dir = tempfile::tempdir().unwrap();
    let dest = dir.path().join("test.mdx");
    std::fs::copy(fixture_path(), &dest).unwrap();

    let dict = opendict::open(dir.path()).unwrap();
    assert_eq!(dict.word_count(), 3);

    let result = dict.lookup("foo").unwrap().unwrap();
    assert_eq!(result.len(), 1);
    assert_eq!(result[0].type_id, 'h'); // Html format
    assert_eq!(String::from_utf8(result[0].data.clone()).unwrap(), "bar");
}

#[test]
fn full_dictionary_word_list() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::copy(fixture_path(), dir.path().join("test.mdx")).unwrap();

    let dict = opendict::open(dir.path()).unwrap();
    let words = dict.word_list();
    assert_eq!(words, vec!["foo", "hello", "test"]);
}

#[test]
fn full_dictionary_prefix_search() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::copy(fixture_path(), dir.path().join("test.mdx")).unwrap();

    let dict = opendict::open(dir.path()).unwrap();
    let results = dict.search_prefix("te", 10);
    assert_eq!(results, vec!["test"]);
}

#[test]
fn full_dictionary_info() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::copy(fixture_path(), dir.path().join("test.mdx")).unwrap();

    let dict = opendict::open(dir.path()).unwrap();
    let info = dict.info();
    assert_eq!(info.name, "Test Dict");
    assert_eq!(info.word_count, 3);
}
